// batch80: utilsCancellation + promise — data-driven from batch80_truth.json
// (truth generated by Node vm against the real TS sources, async awaited).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/commonFacade/cancellation.dart'
    show CancellationTokenSource;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/observableValue.dart'
    as ov;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/utils/promise.dart'
    as pp;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/utils/utilsCancellation.dart'
    as uc;
import 'package:semi_design_flutter/src/monaco/base/common/lifecycle.dart'
    show DisposableStore;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch80_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

Future<void> _tick() => Future<void>.delayed(Duration.zero);

void main() {
  group('batch80 waitForState', () {
    test('default predicate (non-null)', () async {
      final t = _truth()['waitDefault'] as Map<String, dynamic>;
      final o = ov.observableValue<Object?, Object?>('ws', null);
      final future = uc.waitForState<Object?>(o);
      bool resolved = false;
      Object? value;
      future.then((v) {
        resolved = true;
        value = v;
      });
      await _tick();
      expect(resolved, t['beforeSet']);
      o.set(42, null, null);
      await _tick();
      expect(resolved, true);
      expect(value, t['value']);
    });

    test('custom predicate + isError', () async {
      final t = _truth()['waitPredicate'] as Map<String, dynamic>;
      final o = ov.observableValue<int, Object?>('wc', 0);
      final future = uc.waitForState<int>(o, (s) => s >= 5,
          (s) => s == -1 ? 'bad' : false);
      Object? resolves;
      Object? rejects;
      future.then((v) => resolves = v, onError: (e) => rejects = e);
      o.set(3, null, null);
      await _tick();
      final midway = t['midway'] as Map<String, dynamic>;
      expect(resolves, midway['resolves']);
      expect(rejects, midway['rejects']);
      o.set(7, null, null);
      await _tick();
      final finalT = t['final'] as Map<String, dynamic>;
      expect(resolves, finalT['resolves']);
      expect(rejects, finalT['rejects']);
    });

    test('isError=true rejects with state', () async {
      final t = _truth()['waitErrorTrue'] as Map<String, dynamic>;
      final o = ov.observableValue<int, Object?>('we', 0);
      final future = uc.waitForState<int>(o, (s) => s > 0, (s) => s < 0 ? true : false);
      Object? resolves;
      Object? rejects;
      future.then((v) => resolves = v, onError: (e) => rejects = e);
      o.set(-9, null, null);
      await _tick();
      expect(resolves, t['resolves']);
      expect(rejects, t['rejects']);
    });

    test('cancellation rejects with CancellationError', () async {
      final t = _truth()['waitCancel'] as Map<String, dynamic>;
      final o = ov.observableValue<int, Object?>('wx', 0);
      final cts = CancellationTokenSource();
      final future = uc.waitForState<int>(o, (s) => s > 0, null, cts.token);
      Object? resolves;
      Object? rejects;
      cts.cancel();
      try {
        resolves = await future;
      } catch (e) {
        rejects = {'message': e.toString()};
      }
      expect(resolves, t['resolves']);
      expect(rejects, t['rejects']);
    });
  });

  group('batch80 ObservableLazy', () {
    test('computes once, caches', () {
      final t = _truth()['observableLazy'] as Map<String, dynamic>;
      int computes = 0;
      final lazy = pp.ObservableLazy<int>(() {
        computes++;
        return 99;
      });
      expect(computes, t['before']);
      expect(lazy.getValue(), t['v1']);
      expect(lazy.getValue(), t['v2']);
      expect(lazy.cachedValue.get(), t['cachedBefore']);
      expect(computes, t['computes']);
    });
  });

  group('batch80 ObservablePromise', () {
    test('resolved', () async {
      final t = _truth()['observablePromiseResolved'] as Map<String, dynamic>;
      final op = pp.ObservablePromise<int>.resolved(123);
      expect(op.promiseResult.get(), null);
      await _tick();
      final after = op.promiseResult.get();
      expect(after, isNotNull);
      expect(after!.data, t['data']);
      expect(after.error, t['error']);
      expect(op.resolvedValue.get(), t['resolvedValue']);
      String throwResult;
      try {
        after.getDataOrThrow();
        throwResult = 'no-throw';
      } catch (_) {
        throwResult = 'throw';
      }
      expect(throwResult, t['throwResult']);
    });

    test('rejected', () async {
      final t = _truth()['observablePromiseRejected'] as Map<String, dynamic>;
      final op = pp.ObservablePromise<int>(Future<int>.error('oops'));
      bool promiseRejected = false;
      op.promise.catchError((_) {
        promiseRejected = true;
        return 0;
      });
      await _tick();
      expect(promiseRejected, t['promiseRejected']);
      final after = op.promiseResult.get();
      expect(after, isNotNull);
      expect(after!.error != null, t['hasError']);
      expect(after.error.toString(), t['error']);
      expect(after.data, null);
      String throwResult;
      try {
        after.getDataOrThrow();
        throwResult = 'no-throw';
      } catch (e) {
        throwResult = 'throw: $e';
      }
      expect(throwResult, t['throwResult']);
    });

    test('ObservableLazyPromise', () async {
      final t = _truth()['observableLazyPromise'] as Map<String, dynamic>;
      int computes = 0;
      final lp = pp.ObservableLazyPromise<int>(() {
        computes++;
        return Future<int>.value(77);
      });
      expect(computes, t['before']);
      expect(lp.cachedPromiseResult.get(), null);
      final value = await lp.getPromise();
      expect(computes, t['afterGet']);
      expect(value, t['value']);
      await _tick();
      final cached = lp.cachedPromiseResult.get();
      expect(cached, isNotNull);
      expect(cached!.data, t['cachedAfterData']);
    });
  });
}
